def bfs_flood_fill(grid, start_r, start_c, color):
    visited = []
    queue = [(start_r, start_c)]
    visited_set = {(start_r, start_c)}
    while queue:
        r, c = queue.pop()
        visited.append((r, c))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and (nr, nc) not in visited_set:
                if grid[nr][nc] == color:
                    visited_set.add((nr, nc))
                    queue.append((nr, nc))
    return visited

# Labels for each 0 component
input_0s = grids['Demo pair 1 input']
output_0s = grids['Demo pair 1 output']
component_ids = {}
for r in range(len(input_0s)):
    for c in range(len(input_0s[0])):
        if input_0s[r][c] == 0:
            if (r, c) not in component_ids:
