import os, re
from collections import deque

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

grids = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in grids and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        grids[k] = [[int(x) for x in r] for r in rows]

def bfs_ranges(grid, start_r, start_c, label):
    visited = []
    queue = [(start_r, start_c)]
    visited_set = {(start_r, start_c)}
    while queue:
        r, c = queue.pop()
        visited.append((r, c))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and (nr, nc) not in visited_set:
                if grid[nr][nc] == 0:
                    visited_set.add((nr, nc))
                    queue.append((nr, nc))
    return visited

# Check demo input
input_demo = grids['Demo pair 1 input']
output_demo = grids['Demo pair 1 output']

# Find connected components
component_map = {}
for r in range(len(input_demo)):
    for c in range(len(input_demo[0])):
        if input_demo[r][c] == 0:
            if (r, c) not in component_map:
                comp = bfs_ranges(input_demo, r, c, 0)
                for cell in comp:
                    component_map[cell] = len(comp)

# Apply rule: size >= 2 becomes 8
predicted_output = [row[:] for row in input_demo]
for (r, c), size in component_map.items():
    if size >= 2:
        predicted_output[r][c] = 8

print("Dem o prediction vs output:")
for r in range(len(output_demo)):
    if output_demo[r] != predicted_output[r]:
        print(f"Row {r} mismatch:")
        print(f"  output:    {output_demo[r]}")
        print(f"  predicted: {predicted_output[r]}")
    else:
        print(f"Row {r}: OK")

# Now apply to test input
input_test = grids['Test input']
component_map_test = {}
for r in range(len(input_test)):
    for c in range(len(input_test[0])):
        if input_test[r][c] == 0:
            if (r, c) not in component_map_test:
                comp = bfs_ranges(input_test, r, c, 0)
                for cell in comp:
                    component_map_test[cell] = len(comp)

# Build predicted test output
predicted_test = [row[:] for row in input_test]
for (r, c), size in component_map_test.items():
    if size >= 2:
        predicted_test[r][c] = 8

print("\nPredicted test output:")
for row in predicted_test:
    print(f"{' '.join(str(x) for x in row)}")
